import{_ as n,o as a,c as l,a2 as e}from"./chunks/framework.BDmrrkGR.js";const B=JSON.parse('{"title":"236. 二叉树的最近公共祖先（二叉树 / 递归 / DFS）","description":"","frontmatter":{"title":"236. 二叉树的最近公共祖先（二叉树 / 递归 / DFS）","date":"2026-09-13T00:00:00.000Z","tags":["CodeTop","LeetCode","二叉树","递归","DFS","中等"],"category":"codetop","difficulty":"中等","leetcodeId":236,"excerpt":"递归后序遍历寻找二叉树中两个节点的最近公共祖先。"},"headers":[],"relativePath":"posts/leetcode/codetop/code236-lowest-common-ancestor-of-a-binary-tree.md","filePath":"posts/leetcode/codetop/code236-lowest-common-ancestor-of-a-binary-tree.md","lastUpdated":1789257371000}'),o={name:"posts/leetcode/codetop/code236-lowest-common-ancestor-of-a-binary-tree.md"};function p(c,s,t,r,i,d){return a(),l("div",null,[...s[0]||(s[0]=[e(`<h1 id="_236-二叉树的最近公共祖先-二叉树-递归-dfs" tabindex="-1">236. 二叉树的最近公共祖先（二叉树 / 递归 / DFS） <a class="header-anchor" href="#_236-二叉树的最近公共祖先-二叉树-递归-dfs" aria-label="Permalink to &quot;236. 二叉树的最近公共祖先（二叉树 / 递归 / DFS）&quot;">​</a></h1><h2 id="题目" tabindex="-1">题目 <a class="header-anchor" href="#题目" aria-label="Permalink to &quot;题目&quot;">​</a></h2><p>给定一个二叉树，找到该树中两个指定节点的最近公共祖先。<br> 最近公共祖先的定义为：“对于有根树 T 的两个节点 p、q，最近公共祖先表示为一个节点 x，满足 x 是 p、q 的祖先且 x 的深度尽可能大（一个节点也可以是它自己的祖先）。”</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><p>输入：<code>root = [3,5,1,6,2,0,8,null,null,7,4]</code>, <code>p = 5</code>, <code>q = 1</code><br> 输出：<code>3</code><br> 解释：节点 5 和节点 1 的最近公共祖先是节点 3。</p><p>输入：<code>root = [3,5,1,6,2,0,8,null,null,7,4]</code>, <code>p = 5</code>, <code>q = 4</code><br> 输出：<code>5</code><br> 解释：节点 5 和节点 4 的最近公共祖先是节点 5，因为根据定义最近公共祖先节点可以为节点本身。</p><h2 id="解题思路" tabindex="-1">解题思路 <a class="header-anchor" href="#解题思路" aria-label="Permalink to &quot;解题思路&quot;">​</a></h2><p>采用<strong>递归后序遍历（DFS）</strong>。<br> 对于当前节点 <code>root</code>：</p><ul><li>如果 <code>root</code> 为空，或者 <code>root</code> 就是 <code>p</code> 或 <code>q</code>，直接返回 <code>root</code>。</li><li>递归在左子树中查找 <code>p</code> 和 <code>q</code> 的最近公共祖先，结果记为 <code>left</code>。</li><li>递归在右子树中查找，结果记为 <code>right</code>。</li><li>如果 <code>left</code> 和 <code>right</code> 都非空，说明 <code>p</code> 和 <code>q</code> 分别位于左右子树中，当前 <code>root</code> 就是最近公共祖先，返回 <code>root</code>。</li><li>如果只有 <code>left</code> 非空，说明 <code>p</code> 和 <code>q</code> 都在左子树中，返回 <code>left</code>。</li><li>否则返回 <code>right</code>。</li></ul><p>时间复杂度 <code>O(n)</code>，空间复杂度 <code>O(h)</code>（递归栈深度，h 为树高）。</p><h2 id="解答" tabindex="-1">解答 <a class="header-anchor" href="#解答" aria-label="Permalink to &quot;解答&quot;">​</a></h2><div class="language-java line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="color:#7F848E;font-style:italic;">/**</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> * Definition for a binary tree node.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> * public class TreeNode {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> *     int val;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> *     TreeNode left;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> *     TreeNode right;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> *     TreeNode(int x) { val = x; }</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> * }</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> */</span></span>
<span class="line"><span style="color:#C678DD;">class</span><span style="color:#E5C07B;"> Solution</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    public</span><span style="color:#E5C07B;"> TreeNode</span><span style="color:#61AFEF;"> lowestCommonAncestor</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">TreeNode</span><span style="color:#E06C75;font-style:italic;"> root</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">TreeNode</span><span style="color:#E06C75;font-style:italic;"> p</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">TreeNode</span><span style="color:#E06C75;font-style:italic;"> q</span><span style="color:#ABB2BF;">)</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        // 递归终止条件：如果当前节点为空，或者当前节点就是 p 或 q，直接返回当前节点</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        // 为什么返回 root？因为如果 root 是 p 或 q，它可能就是最近公共祖先（一个节点可以是自己的祖先）</span></span>
<span class="line"><span style="color:#C678DD;">        if</span><span style="color:#ABB2BF;"> (root </span><span style="color:#56B6C2;">==</span><span style="color:#D19A66;"> null</span><span style="color:#56B6C2;"> ||</span><span style="color:#ABB2BF;"> root </span><span style="color:#56B6C2;">==</span><span style="color:#ABB2BF;"> p </span><span style="color:#56B6C2;">||</span><span style="color:#ABB2BF;"> root </span><span style="color:#56B6C2;">==</span><span style="color:#ABB2BF;"> q) {</span></span>
<span class="line"><span style="color:#C678DD;">            return</span><span style="color:#ABB2BF;"> root;</span></span>
<span class="line"><span style="color:#ABB2BF;">        }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        // 递归在左子树中查找 p 和 q 的最近公共祖先</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        // 使用 TreeNode 类型接收结果，因为返回的是节点对象</span></span>
<span class="line"><span style="color:#E5C07B;">        TreeNode</span><span style="color:#E06C75;"> left</span><span style="color:#56B6C2;"> =</span><span style="color:#61AFEF;"> lowestCommonAncestor</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">root</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">left</span><span style="color:#ABB2BF;">, p, q);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        // 递归在右子树中查找 p 和 q 的最近公共祖先</span></span>
<span class="line"><span style="color:#E5C07B;">        TreeNode</span><span style="color:#E06C75;"> right</span><span style="color:#56B6C2;"> =</span><span style="color:#61AFEF;"> lowestCommonAncestor</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">root</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">right</span><span style="color:#ABB2BF;">, p, q);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        // 如果左右子树都找到了结果（即 left 和 right 都不为空）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        // 说明 p 和 q 分别位于当前节点的左右两侧，当前节点就是最近公共祖先</span></span>
<span class="line"><span style="color:#C678DD;">        if</span><span style="color:#ABB2BF;"> (left </span><span style="color:#56B6C2;">!=</span><span style="color:#D19A66;"> null</span><span style="color:#56B6C2;"> &amp;&amp;</span><span style="color:#ABB2BF;"> right </span><span style="color:#56B6C2;">!=</span><span style="color:#D19A66;"> null</span><span style="color:#ABB2BF;">) {</span></span>
<span class="line"><span style="color:#C678DD;">            return</span><span style="color:#ABB2BF;"> root;</span></span>
<span class="line"><span style="color:#ABB2BF;">        }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        // 如果只有左子树找到结果，说明 p 和 q 都在左子树中，返回左子树的结果</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        // 如果只有右子树找到结果，说明 p 和 q 都在右子树中，返回右子树的结果</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        // 如果左右都为空，说明当前子树中不包含 p 和 q，返回 null（由上一层处理）</span></span>
<span class="line"><span style="color:#C678DD;">        return</span><span style="color:#ABB2BF;"> left </span><span style="color:#56B6C2;">!=</span><span style="color:#D19A66;"> null</span><span style="color:#C678DD;"> ?</span><span style="color:#ABB2BF;"> left </span><span style="color:#C678DD;">:</span><span style="color:#ABB2BF;"> right;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br></div></div>`,12)])])}const b=n(o,[["render",p]]);export{B as __pageData,b as default};
